"use client";

import { useEffect, useState } from "react";
import { cn } from "@/lib/cn";

export interface InteractiveDiffSliderProps {
  className?: string;
}

export function InteractiveDiffSlider({ className }: InteractiveDiffSliderProps) {
  const [split, setSplit] = useState(50);
  const [auto, setAuto] = useState(true);

  useEffect(() => {
    if (!auto) return;
    let t = 0;
    let frame;
    const loop = () => {
      t += 0.03;
      setSplit(50 + Math.sin(t) * 38);
      frame = requestAnimationFrame(loop);
    };
    frame = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frame);
  }, [auto]);

  return (
    <div className={cn("relative h-60 w-full max-w-md overflow-hidden rounded-xl border border-line bg-paper select-none", className)}>
      {/* Before Face */}
      <div className="absolute inset-0 flex flex-col items-start justify-center p-6 bg-line/10">
        <span className="font-mono text-xs font-bold text-graphite uppercase">BEFORE SPEC</span>
        <span className="font-display text-lg font-bold text-ink mt-1">V1: Wireframe Draft</span>
      </div>

      {/* After Face (Clipped) */}
      <div
        className="absolute inset-0 flex flex-col items-end justify-center p-6 bg-ink text-paper"
        style={{ clipPath: `inset(0 0 0 ${split}%)` }}
      >
        <span className="font-mono text-xs font-bold text-amber-400 uppercase">AFTER SPEC</span>
        <span className="font-display text-lg font-bold text-white mt-1">V2: High-Fi Interactive</span>
      </div>

      {/* Scrubber Line */}
      <div
        className="absolute inset-y-0 w-[2px] bg-red-500 z-10 drop-shadow-[0_0_8px_#ef4444]"
        style={{ left: `${split}%` }}
      >
        <div className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-4 h-4 rounded-full bg-red-500 text-white text-[8px] flex items-center justify-center font-bold">
          ↔
        </div>
      </div>

      <div className="absolute bottom-3 left-1/2 -translate-x-1/2 z-20">
        <input
          type="range"
          min="5"
          max="95"
          value={Math.round(split)}
          onMouseDown={() => setAuto(false)}
          onTouchStart={() => setAuto(false)}
          onChange={(e) => {
            setAuto(false);
            setSplit(parseInt(e.target.value, 10));
          }}
          className="w-36 cursor-pointer accent-red-500"
        />
      </div>
    </div>
  );
}

export default InteractiveDiffSlider;

import { InteractiveDiffSlider } from "./interactive-diff-slider";

export default function Demo() {
  return (
    <div className="flex min-h-[18rem] items-center justify-center bg-paper p-8">
      <InteractiveDiffSlider />
    </div>
  );
}
